// Nodo Code "verificar-firma" (Run Once for All Items).
// Verifica X-Foodzinder-Signature (HMAC-SHA256 del cuerpo crudo) con
// FOODZINDER_WEBHOOK_SECRET. Si no cuadra, lanza: la ejecución queda en rojo
// y nada más se ejecuta. Requiere NODE_FUNCTION_ALLOW_BUILTIN=crypto.
function run(item, env, crypto) {
  const secret = env.FOODZINDER_WEBHOOK_SECRET;
  if (!secret) throw new Error("Falta FOODZINDER_WEBHOOK_SECRET en el entorno de n8n");

  const headers = item.json.headers || {};
  const signature = headers["x-foodzinder-signature"];
  if (!signature) throw new Error("Evento sin cabecera X-Foodzinder-Signature");

  // Con "Raw Body" el cuerpo llega en binary.data (base64); si no, se reserializa el JSON.
  const raw = item.binary && item.binary.data && item.binary.data.data
    ? Buffer.from(item.binary.data.data, "base64").toString("utf8")
    : JSON.stringify(item.json.body);

  const expected = "sha256=" + crypto.createHmac("sha256", secret).update(raw, "utf8").digest("hex");
  const a = Buffer.from(expected, "utf8");
  const b = Buffer.from(String(signature), "utf8");
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error("Firma inválida: el evento no viene de Foodzinder o el secreto no coincide");
  }

  const body = item.json.body && typeof item.json.body === "object" ? item.json.body : JSON.parse(raw);
  return [{ json: { ...body, _delivery: headers["x-foodzinder-delivery"] || null, _verified: true } }];
}

return run($input.first(), $env, require("crypto")); // @n8n-invoke

// Nodo Code "normalizar-evento". Valida la forma del sobre del contrato del P4
// y deja un objeto plano para el Switch y los flujos.
const EVENTS = [
  "user.created",
  "user.became_owner",
  "restaurant.created",
  "restaurant.resubmitted",
  "restaurant.approved",
  "restaurant.rejected",
  "menu.created",
  "review.created",
  "subscription.activated",
  "webhook.test",
];

function run(item) {
  const e = item.json;
  if (e.version !== 1) throw new Error(`Versión de evento no soportada: ${e.version}`);
  if (!e.id || !e.event || !e.occurredAt) throw new Error("Sobre incompleto: faltan id, event u occurredAt");
  if (!EVENTS.includes(e.event)) throw new Error(`Evento desconocido: ${e.event}`);
  return [
    {
      json: {
        id: e.id,
        event: e.event,
        occurredAt: e.occurredAt,
        delivery: e._delivery || null,
        data: e.data || {},
        known: true,
      },
    },
  ];
}

return run($input.first()); // @n8n-invoke

// Flujo 01, nodo "preparar-resumen": del evento restaurant.created/resubmitted
// construye el prompt y el cuerpo de la petición a Gemini.
// Compartido: petición y respuesta de Gemini (generateContent), sin dependencias.
// Se inyecta en los nodos con `// @include shared/gemini`.
// @exports buildGeminiRequest, parseGeminiText, parseGeminiJson

function buildGeminiRequest(prompt, opts) {
  const o = opts || {};
  const generationConfig = {
    temperature: o.temperature == null ? 0.3 : o.temperature,
    maxOutputTokens: o.maxOutputTokens || 400,
    // Gemini 3 razona antes de responder y ese razonamiento consume maxOutputTokens:
    // con "minimal" no gasta nada en pensar y el presupuesto va entero a la respuesta.
    thinkingConfig: { thinkingLevel: o.thinkingLevel || "minimal" },
  };
  if (o.json) generationConfig.responseMimeType = "application/json";
  return {
    contents: [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig,
    safetySettings: [],
  };
}

/** Texto de la primera candidata, o null si la respuesta no tiene la forma esperada (error, bloqueo, timeout). */
function parseGeminiText(response) {
  try {
    const parts = response && response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts;
    if (!parts || !parts.length) return null;
    const text = parts.map((p) => p.text || "").join("").trim();
    return text || null;
  } catch (e) {
    return null;
  }
}

/** Intenta parsear la respuesta como JSON (quitando vallas ```json si las hay). null si no es JSON válido. */
function parseGeminiJson(response) {
  const text = parseGeminiText(response);
  if (!text) return null;
  const cleaned = text.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    return null;
  }
}
